input.sparql:
SELECT ?tsid
WHERE {
  ?chiller a brick:Chiller ;
            rdfs:label "Chiller01" ;
            ref:hasExternalReference/rdf:value ?tsid .
  ?meter brick:measures ?chiller ;
           brick:measures/brick:hasUnits "W" ;
           ref:hasExternalReference/ref:hasTimeseriesId ?tsid .
}
